pub async fn update_space(
    configuration: &configuration::Configuration,
    space_id: &str,
    memory_space_update: models::MemorySpaceUpdate,
    if_match: Option<&str>,
    x_workspace_id: Option<&str>,
) -> Result<Response<models::MemorySpace>, Error<UpdateSpaceError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_path_space_id = space_id;
    let p_body_memory_space_update = memory_space_update;
    let p_header_if_match = if_match;
    let p_header_x_workspace_id = x_workspace_id;

    let uri_str = format!(
        "{}/api/v1/memory-spaces/{space_id}",
        configuration.base_path,
        space_id = crate::generated::apis::urlencode(p_path_space_id)
    );
    let mut req_builder = configuration
        .client
        .request(reqwest::Method::PATCH, &uri_str);

    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    if let Some(param_value) = p_header_if_match {
        req_builder = req_builder.header("If-Match", param_value.to_string());
    }
    if let Some(param_value) = p_header_x_workspace_id {
        req_builder = req_builder.header("X-Workspace-ID", param_value.to_string());
    }
    if let Some(ref token) = configuration.bearer_access_token {
        req_builder = req_builder.bearer_auth(token.to_owned());
    };
    if let Some(ref apikey) = configuration.api_key {
        let key = apikey.key.clone();
        let value = match apikey.prefix {
            Some(ref prefix) => format!("{} {}", prefix, key),
            None => key,
        };
        req_builder = req_builder.header("X-CSRF-Token", value);
    };
    req_builder = req_builder.json(&p_body_memory_space_update);

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();
    let headers = resp.headers().clone();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("application/octet-stream");
    let content_type = super::ContentType::from(content_type);

    if !status.is_client_error() && !status.is_server_error() {
        let content = resp.text().await?;
        match content_type {
            ContentType::Json => serde_json::from_str(&content)
                .map(|data| Response {
                    data,
                    status,
                    headers,
                })
                .map_err(Error::from),
            ContentType::Text => {
                return Err(Error::from(serde_json::Error::custom(
                    "Received `text/plain` content type response that cannot be converted to `models::MemorySpace`",
                )));
            }
            ContentType::Unsupported(unknown_type) => {
                return Err(Error::from(serde_json::Error::custom(format!(
                    "Received `{unknown_type}` content type response that cannot be converted to `models::MemorySpace`"
                ))));
            }
        }
    } else {
        let content = resp.text().await?;
        let entity: Option<UpdateSpaceError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(Box::new(ResponseContent {
            status,
            headers,
            content,
            entity,
        })))
    }
}
